#include <bits/stdc++.h>
using namespace std;
int fact[12];
int rankp(const vector<int>&v){int r=0;for(int i=0;i<(int)v.size();i++){int c=0;for(int j=i+1;j<(int)v.size();j++)c+=v[j]<v[i];r+=c*fact[v.size()-1-i];}return r;}
bool matches(const vector<int>&v,const vector<int>&p){for(int i=0;i<(int)p.size();i++)for(int j=0;j<i;j++)if((v[i]<v[j])!=(p[i]<p[j]))return false;return true;}
vector<int> sc(const vector<int>&v,const vector<int>&p){vector<int>s,o;int i=0,k=p.size();while(i<(int)v.size()||!s.empty()){bool bad=false;if(i<(int)v.size()&&(int)s.size()>=k-1){vector<int>t{v[i]};for(int j=0;j<k-1;j++)t.push_back(s[s.size()-1-j]);bad=matches(t,p);}if(i<(int)v.size()&&!bad)s.push_back(v[i++]);else{o.push_back(s.back());s.pop_back();}}return o;}
bool avoids(const vector<int>&v,const vector<int>&p){auto q=p;reverse(q.begin(),q.end());for(int i=0;i+(int)p.size()<=(int)v.size();i++){vector<int>t(v.begin()+i,v.begin()+i+p.size());if(matches(t,p)||matches(t,q))return false;}return true;}
int lcs(string a,string b){int dp[260]={};for(char x:a){int prev=0;for(int j=1;j<=(int)b.size();j++){int old=dp[j];dp[j]= x==b[j-1]?prev+1:max(dp[j],dp[j-1]);prev=old;}}return dp[b.size()];}
int score(string w){int best=0,n=w.size(),m=n/2;w+=w;for(int i=0;i<m;i++){string a=w.substr(i,m),b=w.substr(i+m,m);reverse(b.begin(),b.end());for(char &c:b)c=c=='0'?'1':'0';best=max(best,lcs(a,b));}return best;}
int main(int argc,char**argv){fact[0]=1;for(int i=1;i<12;i++)fact[i]=i*fact[i-1];string mode=argv[1];if(mode=="stack"){
 int n=atoi(argv[2]),k=atoi(argv[3]);vector<int>p(k);iota(p.begin(),p.end(),0);int pats=0;do{vector<int>v(n);iota(v.begin(),v.end(),0);vector<int>to(fact[n]),ind(fact[n]),want(fact[n]);int i=0;do{to[i]=rankp(sc(v,p));ind[to[i]]++;want[i]=avoids(v,p);i++;}while(next_permutation(v.begin(),v.end()));queue<int>q;for(i=0;i<fact[n];i++)if(!ind[i])q.push(i);while(!q.empty()){i=q.front();q.pop();if(!--ind[to[i]])q.push(to[i]);}int bad=0,per=0;for(i=0;i<fact[n];i++){per+=ind[i]>0;bad+=(ind[i]>0)!=want[i];}cout<<"pattern ";for(int x:p)cout<<x+1;cout<<" n "<<n<<" tested "<<fact[n]<<" periodic "<<per<<" mismatches "<<bad<<endl;pats++;}while(next_permutation(p.begin(),p.end()));cout<<"patterns "<<pats<<endl;
 }else{mt19937 gen(95001);for(int n:{6,12,18,36,42,48,60,90,120}){int tests=0,best=n;string bw;int reps=n<=18?1:160;string w(n/2,'0');w+=string(n/2,'1');if(n<=18){do{int z=score(w);if(z<best)best=z,bw=w;tests++;}while(next_permutation(w.begin(),w.end()));}else for(int rep=0;rep<reps;rep++){shuffle(w.begin(),w.end(),gen);int s=score(w);for(int step=0;step<180;step++){int a=gen()%n,b=gen()%n;if(w[a]==w[b])continue;swap(w[a],w[b]);int t=score(w);tests++;if(t<=s||(gen()%1000)<8)s=t;else swap(w[a],w[b]);if(s<best)best=s,bw=w;}}cout<<"n "<<n<<" evaluated "<<tests<<" min_max_lcs "<<best<<" target "<<n/3<<" word "<<bw<<endl;}}
}
